{
  "items": [
    {
      "title": "World Bank – World Development Indicators (WDI)",
      "url_or_doi": "https://databank.worldbank.org/source/world-development-indicators",
      "justification": "One of the most comprehensive datasets for comparing economic conditions across all 36 requested European countries and economies, including Kosovo, Moldova, Georgia, Turkey, and the Western Balkans. Provides annual data for the 2020s on GDP, GDP per capita, economic growth, inflation, unemployment, trade, foreign direct investment, government finances, poverty, and income inequality. Particularly useful for constructing a standardized cross-country economic panel covering 2020–2026, subject to data availability."
    },
    {
      "title": "International Monetary Fund – World Economic Outlook Database, October 2026",
      "url_or_doi": "https://data.imf.org/datasets/WEO",
      "justification": "Provides internationally comparable macroeconomic indicators for the requested countries, including real GDP growth, nominal GDP, GDP per capita, purchasing power parity, consumer price inflation, unemployment, government debt, fiscal balances, and current account balances. The October 2026 edition includes historical observations and forecasts through 2031. Particularly valuable for analyzing economic developments during the COVID-19 pandemic, subsequent inflation shocks, and the economic recovery of the 2020s."
    },
    {
      "title": "IMF – World Economic Outlook DataMapper",
      "url_or_doi": "https://www.imf.org/external/datamapper/datasets/WEO",
      "justification": "Provides an accessible interface for comparing major macroeconomic indicators across European economies. Includes GDP growth, inflation, unemployment, public debt, fiscal balances, and external accounts. Covers historical data for the 2020s alongside economic projections. Useful for identifying regional economic differences between EU member states, EU candidate countries, the United Kingdom, Turkey, Moldova, and Georgia."
    },
    {
      "title": "European Commission – AMECO Macroeconomic Database",
      "url_or_doi": "https://economy-finance.ec.europa.eu/economic-research-and-databases/economic-databases/ameco-database/download-annual-data-set-macro-economic-database-ameco_en",
      "justification": "The European Commission's annual macroeconomic database contains detailed economic indicators for EU member states, candidate countries, and other OECD economies. Includes GDP, private consumption, investment, employment, unemployment, wages, productivity, inflation, government expenditure, fiscal balances, and public debt. The November 2026 release provides a particularly relevant source for studying economic conditions across Europe during the 2020s. Country coverage varies by indicator."
    },
    {
      "title": "Eurostat – Gross Domestic Product and Main Components, Annual Data",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/product/view/nama_10_gdp",
      "justification": "Provides official national accounts data on GDP and its expenditure, income, and production components. Particularly valuable for Belgium, Bulgaria, Czechia, Denmark, Germany, Estonia, Ireland, Greece, Spain, France, Italy, Cyprus, Latvia, Lithuania, Luxembourg, Hungary, Malta, the Netherlands, Austria, Poland, Portugal, Romania, Slovenia, Slovakia, Finland, Sweden, and Croatia. Supports detailed analysis of economic growth, household consumption, investment, government expenditure, and trade during the 2020s."
    },
    {
      "title": "Eurostat – Gross Domestic Product at Market Prices, Annual Data",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/product/view/tipsna10",
      "justification": "Contains standardized annual GDP indicators for European economies. Useful for comparing national economic output, economic growth, and differences in economic performance during 2020–2026. Especially relevant for studying the economic effects of the pandemic, subsequent recovery, and changing economic conditions across EU member states."
    },
    {
      "title": "Eurostat – Harmonised Index of Consumer Prices, Monthly Data",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/product/page/prc_hicp_minr",
      "justification": "Provides harmonized monthly consumer price indices and inflation rates for European economies. Particularly important for examining the inflation surge of 2021–2023 and subsequent developments in the 2020s. Enables comparisons of inflation trends across EU countries and participating non-EU European economies. The current dataset replaces the discontinued historical HICP monthly index dataset."
    },
    {
      "title": "Eurostat – Harmonised Index of Consumer Prices, Historical Monthly Data, 1996–2025",
      "url_or_doi": "https://doi.org/10.2908/prc_hicp_midx",
      "justification": "Contains historical monthly harmonized consumer price indices, including observations throughout 2020–2025. Covers EU member states and several non-EU European economies, including the United Kingdom, Turkey, Serbia, Montenegro, North Macedonia, Albania, and Kosovo. Useful for examining inflation during the pandemic and the European energy-price crisis. This historical series has been discontinued and replaced by the newer HICP dataset."
    },
    {
      "title": "Eurostat – Harmonised Index of Consumer Prices, First Released Data",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/product/page/prc_hicp_fpd",
      "justification": "Preserves consumer price indices and inflation rates as originally published, including monthly and annual rates of change. Particularly useful for investigating inflation during the 2020s without introducing later statistical revisions. Supports research into inflation shocks, price stability, and the timing of published economic information across European countries."
    },
    {
      "title": "Eurostat – Unemployment by Sex and Age, Monthly Data",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/view/une_rt_m/default/table",
      "justification": "Provides harmonized monthly unemployment rates, including breakdowns by sex and age, for European economies. Suitable for examining labor-market conditions during the COVID-19 recession, subsequent employment recovery, and later economic fluctuations. Particularly useful for comparing youth unemployment, overall unemployment, and labor-market resilience across EU member states during the 2020s."
    },
    {
      "title": "Eurostat – European Economic Indicators for Short-Term Analysis",
      "url_or_doi": "https://ec.europa.eu/eurostat/cache/metadata/en/euroind_esms.htm",
      "justification": "Describes Eurostat's short-term European economic indicator datasets, covering GDP, inflation, employment, unemployment, business activity, and other economic measures. Useful for identifying harmonized monthly and quarterly statistical series for analyzing European economic developments throughout the 2020s. The metadata connects related datasets and explains their statistical definitions."
    },
    {
      "title": "European Commission – Eurostat Economic and Financial Statistics Database",
      "url_or_doi": "https://ec.europa.eu/eurostat/data/database",
      "justification": "Provides access to detailed official European statistical datasets covering national accounts, prices, government finance, international trade, labor markets, business activity, and household economic conditions. Particularly suitable for constructing a multidimensional economic dataset covering the 27 EU member states and selected non-EU European economies during the 2020s. Data availability differs by country and statistical series."
    },
    {
      "title": "World Bank – Western Balkans Regular Economic Report",
      "url_or_doi": "https://www.worldbank.org/en/region/eca/publication/western-balkans-regular-economic-report",
      "justification": "A particularly relevant regional source covering Albania, Bosnia and Herzegovina, Kosovo, Montenegro, North Macedonia, and Serbia. Its semiannual editions contain economic indicators and supporting statistical tables covering GDP growth, employment, inflation, fiscal balances, public debt, investment, and external trade. The Autumn 2026 edition and earlier reports support analysis of economic conditions and structural challenges in the Western Balkans throughout the 2020s."
    },
    {
      "title": "European Bank for Reconstruction and Development – Transition Report 2026–27",
      "url_or_doi": "https://www.ebrd.com/home/news-and-events/publications/economics/transition-reports/transition-report-2026-27/chapters.html",
      "justification": "Provides economic assessments and indicators for many Central, Eastern, and Southeastern European economies, including the Western Balkans, Moldova, Georgia, and Turkey. Particularly useful for studying economic transition, structural reforms, investment conditions, productivity, and macroeconomic developments. Complements conventional GDP and inflation datasets with information on the institutional and structural factors shaping economic performance during the 2020s."
    },
    {
      "title": "IMF – Fiscal Monitor Database",
      "url_or_doi": "https://www.imf.org/external/datamapper/OEMDC",
      "justification": "The IMF DataMapper provides access to Fiscal Monitor indicators alongside other macroeconomic datasets. Covers government debt, fiscal balances, and related public-finance indicators for European economies. Especially relevant for comparing the fiscal consequences of pandemic support measures, energy subsidies, rising interest rates, and government borrowing during the 2020s. Individual country coverage and historical completeness vary."
    },
    {
      "title": "IMF – International Macroeconomic and Financial Statistics Data Portal",
      "url_or_doi": "https://www.imf.org/en/data",
      "justification": "Provides access to multiple official international datasets covering national accounts, balance of payments, international investment positions, consumer prices, monetary statistics, financial indicators, and government finances. Useful for supplementing World Economic Outlook data with more detailed economic and financial indicators. Particularly valuable for comparative research involving EU countries, the United Kingdom, Turkey, the Western Balkans, Moldova, and Georgia during the 2020s."
    },
    {
      "title": "German Federal Statistical Office – European Economy and Finance Indicators",
      "url_or_doi": "https://www.destatis.de/Europa/EN/Topic/Key-indicators/EconomyFinance.html",
      "justification": "Provides a comparative overview of European economic indicators sourced primarily from Eurostat. Includes GDP, economic growth, inflation, government deficits, and public debt. Particularly useful for rapidly comparing the economic performance of European countries and identifying relevant underlying Eurostat datasets for detailed research on the 2020s."
    },
    {
      "title": "Eurostat – Harmonised Consumer Prices, Monthly Inflation Rates of Change",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/product/view/prc_hicp_mmor",
      "justification": "Contains historical monthly inflation-rate changes for European countries, including the EU member states and selected non-EU economies. Useful for examining short-term price pressures and the evolution of inflation during the 2020s. The historical observations through 2025 support analysis of the pandemic, supply-chain disruptions, and European inflation shocks. For subsequent observations, the newer HICP datasets should be consulted."
    },
    {
      "title": "European Commission – AMECO Population, Employment, and Unemployment Indicators",
      "url_or_doi": "https://economy-finance.ec.europa.eu/economic-research-and-databases/economic-databases/ameco-database/download-annual-data-set-macro-economic-database-ameco_en",
      "justification": "The employment and population components of AMECO provide annual indicators on population, labor force, unemployment, employment, self-employment, and full-time-equivalent employment. These indicators are particularly useful for analyzing labor-market changes and economic resilience during the 2020s. They also allow comparisons between EU member states and selected candidate and OECD countries."
    },
    {
      "title": "World Bank – Western Balkans Economic Developments and Outlook, Autumn 2026",
      "url_or_doi": "https://www.worldbank.org/en/region/eca/publication/western-balkans-regular-economic-report",
      "justification": "The Autumn 2026 edition of the Western Balkans Regular Economic Report provides recent economic assessments, historical indicators, and forecasts for Albania, Bosnia and Herzegovina, Kosovo, Montenegro, North Macedonia, and Serbia. Particularly relevant for comparing economic growth, inflation, labor markets, trade, and fiscal conditions across these six economies. It offers regional context that is not always available in EU-focused datasets."
    }
  ]
}
